mapper.select:
SELECT distinct A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text FROM PTL_PORTFOLIO A INNER JOIN PTL_PORTFOLIO_AUTHORITY ON A.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
A.PORTFOLIO_ID LIKE CONCAT(#{search,jdbcType=VARCHAR},'%') OR A.PORTFOLIO_NAME LIKE CONCAT(#{search,jdbcType=VARCHAR},'%')
AND A.PORTFOLIO_ID = #{initValue,jdbcType=VARCHAR}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName}

SELECT distinct COUNTER_ID AS id, COUNTER_NAME AS text FROM MST_COUNTER_PARTY
(COUNTER_ID LIKE CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%')) or COUNTER_NAME LIKE CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%')) )
AND COUNTER_ID = #{initValue,jdbcType=VARCHAR}

SELECT distinct COUNTER_ID AS code, COUNTER_NAME AS shortName FROM MST_COUNTER_PARTY
(COUNTER_ID LIKE CONCAT('%',CONCAT(#{counterId,jdbcType=VARCHAR},'%')) or COUNTER_NAME LIKE CONCAT('%',CONCAT(#{counterId,jdbcType=VARCHAR},'%')) )
AND COUNTER_ID = #{counterId,jdbcType=VARCHAR}

select p.PORTFOLIO_ID,p.PORTFOLIO_NAME, td.TRADE_ID, dict.ITEM_VALUE tradeMarket, td.FINPROD_TYPE2, td.TRADE_DATE, td.MDATE-td.VDATE term_days, td.FINPROD_TYPE2 repoType, td.VDATE, td.TRADE_AMT, mcp.COUNTER_NAME counterId, td.COUNTER_TRADER, td.SEC_MANAGE_ACCT_ID acct_id, dict2.ITEM_VALUE registOrg, tda.RELEASE_STATUS release_status, tsai.SEC_ACCT_NAME acctName, td.PRIN_AMT prinAmt,tp.M_TRADE_AMT mtradeAmt from TRD_PRODUCT_DEAL td LEFT JOIN TRD_PRODUCT_DEAL_ADD tda on tda.trade_id = td.trade_id LEFT JOIN FIN_TRADE_PRODUCT tp on tp.finprod_id=td.finprod_id LEFT JOIN PTL_TRADE PT ON td.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO p on p.portfolio_id=PT.portfolio_id LEFT JOIN SYS_DATADICT_LIST dict ON td.trade_market=dict.item_code and dict.dict_code='TRADE_PLACE' LEFT JOIN SYS_DATADICT_LIST dict2 ON td.regist_org=dict2.item_code and dict2.dict_code='REGIST_ORG' LEFT JOIN MST_COUNTER_PARTY mcp ON mcp.COUNTER_ID = TD.COUNTER_ID LEFT JOIN STL_SEC_ACCT_INFO tsai on tsai.sec_acct_id=td.SEC_MANAGE_ACCT_ID LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = td.TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = td.TRADE_ID AND fpt.BRANCH = '0'
td.FINPROD_TYPE2='F02' and p.INVEST_YESORNO = 'Y' and td.MDATE = #{ptDate,jdbcType=DATE} AND (td.IS_CANCEL is null or td.IS_CANCEL = 'N') AND td.TRADE_STATUS = '01' AND ptpd.PA_BUSS_TYPE IN ('19', '20') AND fpt.TYPE_6 = 'H01'
AND (p.PORTFOLIO_ID IN (SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{userName}) OR p.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userName}))
AND (p.PORTFOLIO_ID = #{portfolioId} OR p.PARENT_PORTFOLIO_ID=#{portfolioId} )
AND td.TRADE_DATE BETWEEN TO_DATE(#{dataDateStart},'YYYY-MM-DD') AND TO_DATE(#{dataDateEnd},'YYYY-MM-DD')
and td.TRADE_MARKET = #{tradeMarket}
and td.COUNTER_ID =#{counterId}
and td.SEC_MANAGE_ACCT_ID = #{acctId}
and NVL(tda.RELEASE_STATUS, '0') = #{releaseStatus}
AND td.TRADE_MARKET IN
#{item}
AND td.REGIST_ORG IN
#{item}

select p.PORTFOLIO_ID,p.PORTFOLIO_NAME, td.TRADE_ID, dict.ITEM_VALUE tradeMarket, td.FINPROD_TYPE2, td.TRADE_DATE, td.MDATE, td.VDATE, td.MDATE-td.VDATE term_days, td.TRADE_AMT, td.FINPROD_TYPE2 repoType, mcp.COUNTER_NAME counterId, td.COUNTER_TRADER, td.SEC_MANAGE_ACCT_ID ACCT_ID, dict2.ITEM_VALUE registOrg, tda.RELEASE_STATUS release_status, tsai.SEC_ACCT_NAME acctName, td.PRIN_AMT prinAmt,tp.M_TRADE_AMT mtradeAmt from TRD_PRODUCT_DEAL td LEFT JOIN TRD_PRODUCT_DEAL_ADD tda on tda.TRADE_ID = td.TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT tp on tp.FINPROD_ID=td.FINPROD_ID LEFT JOIN FIN_PRODUCT f on f.FINPROD_ID = td.FINPROD_ID LEFT JOIN PTL_TRADE PT on td.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO p on p.PORTFOLIO_ID=PT.PORTFOLIO_ID LEFT JOIN SYS_DATADICT_LIST dict ON td.TRADE_MARKET=dict.ITEM_CODE and dict.DICT_CODE='TRADE_PLACE' LEFT JOIN SYS_DATADICT_LIST dict2 ON td.REGIST_ORG=dict2.ITEM_CODE and dict2.DICT_CODE='REGIST_ORG' LEFT JOIN MST_COUNTER_PARTY mcp ON mcp.COUNTER_ID = TD.COUNTER_ID Left JOIN STL_SEC_ACCT_INFO tsai on tsai.SEC_ACCT_ID=td.SEC_MANAGE_ACCT_ID LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = td.TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = td.TRADE_ID AND fpt.BRANCH = '0'
td.finprod_type2='F03' AND td.mdate = #{ptDate,jdbcType=DATE} AND p.INVEST_YESORNO = 'Y' AND (td.IS_CANCEL is null or td.IS_CANCEL = 'N') AND td.TRADE_STATUS = '01' AND ptpd.PA_BUSS_TYPE IN ('19', '20') AND fpt.TYPE_6 = 'H01'
AND (p.PORTFOLIO_ID IN (SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{userName}) OR p.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userName}))
AND (p.PORTFOLIO_ID = #{portfolioId} OR p.PARENT_PORTFOLIO_ID=#{portfolioId} )
AND td.TRADE_DATE BETWEEN TO_DATE(#{dataDateStart},'YYYY-MM-DD') AND TO_DATE(#{dataDateEnd},'YYYY-MM-DD')
and td.TRADE_MARKET = #{tradeMarket}
and td.COUNTER_ID =#{counterId}
and td.SEC_MANAGE_ACCT_ID = #{acctId}
and NVL(tda.RELEASE_STATUS, '0') = #{releaseStatus}
AND td.TRADE_MARKET IN
#{item}

        select T1.PORTFOLIO_ID,T1.SEC_ACCT_ID,T1.FINPROD_ID,T1.BRANCH,T1.INV_AIM,T1.HODING_TYPE
               ,T1.CDATE,T1.CCY,T1.AMOUNT,T1.P_FINPROD_ID,T1.FACE_VALUE
        from PTL_SEC_POSITION T1

          T1.CDATE =  #{ptDate,jdbcType=DATE}	                 
		  and T1.PORTFOLIO_ID = #{portfolioId}
		  and T1.FINPROD_ID = #{secId}
		  and T1.HODING_TYPE=#{hodingtype}
		  and T1.INV_AIM in('FVTPL','FVOCI','AC') order by T1.INV_AIM desc

SELECT T1.MY_ACCT_NO from STL_PAY_ORDERS T1

 T1.TRADE_ID = #{tradeid,jdbcType=VARCHAR}
 AND T1.PAY_TYPE='01'
